<div class="container">
    <h2>SillyTavern 数据侦测器</h2>
    <p>下方将显示从 <code>getChatMessages()</code> 获取到的最新一条消息的完整数据结构。</p>

    <div id="output">
        <p>正在尝试获取数据...</p>
    </div>
</div>

<script>
    async function inspectData() {
        const outputEl = document.getElementById('output');

        try {
            // Check if the function exists
            if (typeof getChatMessages !== 'function' || typeof getCurrentMessageId !== 'function') {
                outputEl.innerHTML = `<p class="error">错误：未找到 getChatMessages() 或 getCurrentMessageId() 函数。请确保在支持的环境中运行。</p>`;
                return;
            }

            const messages = await getChatMessages(getCurrentMessageId());

            if (!messages || messages.length === 0) {
                outputEl.innerHTML = `<p class="error">未获取到任何消息。请先进行一次对话再刷新。</p>`;
                return;
            }

            // We got the message object!
            const latestMessage = messages[0];

            // Convert the entire object to a nicely formatted JSON string
            const dataString = JSON.stringify(latestMessage, null, 2); // The '2' makes it nicely indented

            outputEl.innerHTML = `
                <p class="success">成功获取到最新消息！其完整内容如下：</p>
                <pre>${dataString}</pre>
            `;

        } catch (error) {
            outputEl.innerHTML = `
                <p class="error">在执行过程中发生严重错误：</p>
                <pre>${error.stack}</pre>
            `;
        }
    }

    document.addEventListener('DOMContentLoaded', inspectData);
</script>

</body>
