                barColor = getCrashColor(numericValue);
            }

            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            progressBar.style.backgroundColor = barColor;
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || !messages[0] || !messages[0].data) throw new Error("无法加载消息或数据");

            const gameData = messages[0].data;
            const characterData = gameData.stat_data;
            if (!characterData) throw new Error("stat_data 未找到");

            const worldDateElement = document.getElementById('world-date');
            if (worldDateElement && characterData.世界) {
                const day = SafeGetValue(characterData, '世界.天数');
                if (day !== "N/A") worldDateElement.innerText = `第 ${day} 天`;
            }

            if (characterData.林清月) {
                updateProgressBar('lin-affection-bar', 'lin-affection', SafeGetValue(characterData, '林清月.好感度'), 0, 100, 'affection');
                updateProgressBar('lin-crash-bar', 'lin-crash', SafeGetValue(characterData, '林清月.崩溃度'), 0, 100, 'crash');
            }

            if (characterData.顾星) {
                updateProgressBar('gu-affection-bar', 'gu-affection', SafeGetValue(characterData, '顾星.好感度'), 0, 100, 'affection');
                updateProgressBar('gu-crash-bar', 'gu-crash', SafeGetValue(characterData, '顾星.崩溃度'), 0, 100, 'crash');
            }

            const linTab = document.getElementById('tab-lin-qingyue');
            if (linTab) {
                linTab.style.borderBottomColor = getAffectionColor(SafeGetValue(characterData, '林清月.好感度'));
                switchTab('lin-qingyue', linTab);
            }

        } catch (error) {
            const card = document.getElementById('status-card');
            if(card) card.innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function switchTab(characterKey, clickedButton) {
        document.querySelectorAll('.content-panel').forEach(p => p.style.display = 'none');
        document.querySelectorAll('.tab-button').forEach(b => {
            b.classList.remove('active');
            b.style.borderBottomColor = 'transparent';
        });

        const activePanel = document.getElementById(characterKey + '-panel');
        if (activePanel) activePanel.style.display = 'block';

        if (clickedButton) {
            clickedButton.classList.add('active');
            const affectionValue = SafeGetValue(window.characterDataForTabs, `${characterKey === 'lin-qingyue' ? '林清月' : '顾星'}.好感度`, 0);
            clickedButton.style.borderBottomColor = getAffectionColor(affectionValue);
        }
    }

    window.characterDataForTabs = {};
    (async () => {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (messages && messages[0] && messages[0].data && messages[0].data.stat_data) {
                window.characterDataForTabs = messages[0].data.stat_data;
            }
        } catch (e) { /* silent fail */ }

        document.addEventListener('DOMContentLoaded', initDisplay);
    })();
</script>
</body>
</html>
